insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0003-0000-4000-8000-000000000009', 'en', null, 'Project Management Fundamentals', 'A first course in how projects are planned and delivered — the project lifecycle, predictive (waterfall) and agile approaches, scope, schedule, cost, risk, stakeholders, and teams. Structure references the PMI (Project Management Institute) published CAPM outline and targets CAPM-style foundations; all prose and examples are original.', null, 'work', 9, true, 'business', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0003-0000-4000-8000-000000000009', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"A project is best described as…","options":["ongoing operational work that repeats","a temporary effort to create a unique result","any task that takes longer than a day","a department in a company"],"answer":1,"explanation":"Projects are temporary and produce a unique product, service, or result — unlike ongoing operations."},{"prompt":"The ''triple constraint'' of a project refers to…","options":["people, process, tools","scope, schedule, cost","plan, do, review","risk, quality, change"],"answer":1,"explanation":"Scope, schedule (time), and cost are the classic competing constraints — see ''Cost and the triple constraint''."},{"prompt":"A predictive (waterfall) approach works best when…","options":["requirements change constantly","requirements are well understood up front","there is no schedule","the team refuses documentation"],"answer":1,"explanation":"Predictive plans a fixed scope early; it suits stable, well-defined work."},{"prompt":"In agile, work is delivered in…","options":["one large final release","short iterations with regular feedback","random order","a single design phase"],"answer":1,"explanation":"Agile delivers value incrementally in short iterations and adapts to feedback."},{"prompt":"A Work Breakdown Structure (WBS) is…","options":["a list of team members","a hierarchical decomposition of the project''s deliverables","the project budget","a risk log"],"answer":1,"explanation":"The WBS breaks total scope into smaller, manageable deliverables and work packages."},{"prompt":"A stakeholder is…","options":["only the person paying for the project","anyone who can affect or is affected by the project","only the project manager","only the software developers"],"answer":1,"explanation":"Stakeholders include anyone with an interest in or influence over the project."},{"prompt":"A risk in project terms is…","options":["something that has already gone wrong","an uncertain event that could affect objectives","a guaranteed cost","a type of meeting"],"answer":1,"explanation":"A risk is uncertain; it may be a threat or an opportunity — see ''Risk and stakeholders''."},{"prompt":"The document that formally authorizes a project and names the sponsor is the…","options":["project charter","status report","invoice","retrospective"],"answer":0,"explanation":"The project charter authorizes the project and gives the manager authority."}]}'::jsonb, null, 10),
  (2, 'What a project is, and the project lifecycle', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Define a project, distinguish it from operations, and name the phases of a project lifecycle. Warm-up: from the diagnostic, what two words separate a project from ongoing operations?"},{"heading":"The idea","text":"A *project* is a *temporary* effort — it has a start and an end — that creates a *unique* result: a product, a service, or an outcome. Building one specific bridge is a project; running a toll booth every day is *operations*. Most projects move through a *lifecycle*: **initiating** (define why and get authorization via the charter), **planning** (decide scope, schedule, cost, and risks), **executing** (do the work and build deliverables), **monitoring and controlling** (compare progress to plan and adjust), and **closing** (hand over, capture lessons learned). These phases overlap in practice."},{"heading":"Worked example","text":"A city wants a new library website. Initiating: the sponsor signs a charter naming the goal and budget. Planning: the team lists pages, sets a launch date, and estimates cost. Executing: designers and developers build. Monitoring: weekly checks catch a slipping page. Closing: the site goes live, the team writes down what to do better next time."},{"heading":"Your turn","text":"Label each as project (P) or operations (O): (1) migrating a company to a new email system, (2) answering the daily support queue, (3) launching a first-ever mobile app, (4) processing monthly payroll. Answers: 1-P, 2-O, 3-P, 4-O."},{"heading":"Common mistakes & exit ticket","text":"Mistake: calling every task a ''project'' — repeating, steady-state work is operations. Mistake: thinking phases run in a strict, never-overlapping line. Exit: (a) Which phase produces the charter? (b) Name the phase where deliverables are actually built. Answers: initiating; executing."}]}'::jsonb, 'Remember: temporary + unique = project; repeating = operations.', 12),
  (3, 'Predictive (waterfall) vs agile approaches', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Contrast predictive and agile delivery and choose the right approach for a situation. Warm-up: which approach fixes scope early — waterfall or agile?"},{"heading":"The idea","text":"*Predictive* (also called *waterfall* or plan-driven) sets scope, schedule, and cost as baselines up front, then works through phases in sequence; changes go through formal change control. It fits stable work with well-understood requirements, like construction. *Agile* (adaptive) delivers in short *iterations* (often called sprints), reviewing working results with stakeholders and re-planning each cycle. It fits uncertain, fast-changing work like new software, where feedback shapes the product. Many real teams use a *hybrid*: a predictive backbone with agile delivery inside it. Agile keeps a *backlog* of prioritized work and favors small, frequent releases."},{"heading":"Worked example","text":"Two teams build a customer portal. The predictive team writes a full specification, gets sign-off, then builds for six months and demos once at the end — a late surprise if requirements were wrong. The agile team ships a login and one feature in two weeks, demos it, learns users want single sign-on, and re-prioritizes the backlog for the next iteration — cheaper to correct course early."},{"heading":"Your turn","text":"Predictive (P) or agile (A)? (1) A regulated bridge with fixed engineering specs, (2) a startup''s experimental app with unclear features, (3) a payroll system upgrade with a legally fixed go-live date, (4) a marketing site refined weekly from user feedback. Answers: 1-P, 2-A, 3-P, 4-A."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking agile means ''no plan'' — agile plans continuously in small increments. Mistake: assuming one approach is always superior; the right choice depends on uncertainty and change. Exit: (a) Which approach reviews working results every iteration? (b) What is a hybrid approach? Answers: agile; a blend of predictive and agile elements."}]}'::jsonb, 'Predictive = plan-then-build; agile = build-and-learn in iterations. Hybrid mixes both.', 13),
  (4, 'Scope, schedule, and the Work Breakdown Structure', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Build a simple Work Breakdown Structure and find the critical path of a schedule. Warm-up: what does a WBS break down — the team, or the deliverables?"},{"heading":"The idea","text":"*Scope* is the total work required to deliver the project. To manage it, you decompose it into a *Work Breakdown Structure (WBS)* — a hierarchy of deliverables broken into *work packages* small enough to estimate and assign. From the WBS you sequence activities, estimate durations, and build a *schedule*. Some tasks depend on others; the *critical path* is the longest chain of dependent tasks, and it sets the shortest possible project duration. Any delay on the critical path delays the whole project; tasks off it have *slack*. Watch out for *scope creep* — uncontrolled additions that quietly blow the schedule and cost."},{"heading":"Worked example","text":"Plan a small event. Activities and durations: Book venue (2 days) → Send invites (1 day) → Arrange catering (3 days); catering can only start after the venue is booked. In parallel: Design posters (4 days) after the venue is booked. Path A: venue → invites = 2+1 = 3 days. Path B: venue → catering = 2+3 = 5 days. Path C: venue → posters = 2+4 = 6 days. The *critical path* is C at 6 days — that is the earliest the event can be ready. Invites have 3 days of slack."},{"heading":"Your turn","text":"Two independent chains run in parallel from the start: Chain 1 is A (4d) → C (3d); Chain 2 is B (5d), which depends on nothing. (1) How long is Chain 1? (2) What is the critical path duration? (3) How much slack does Chain 2 (task B) have? Answers: (1) 4+3 = 7 days, (2) 7 days (Chain 1 is critical), (3) B has 7 − 5 = 2 days of slack."},{"heading":"Common mistakes & exit ticket","text":"Mistake: confusing the WBS with a to-do list — the WBS is organized around deliverables, not a flat task list. Mistake: thinking the critical path is the path with the most tasks (it is the longest by *duration*). Exit: (a) What sets the shortest possible project duration? (b) Name uncontrolled scope growth in two words. Answers: the critical path; scope creep."}]}'::jsonb, 'Decompose scope into a WBS before you estimate the schedule. The critical path is the longest path of dependent tasks.', 13),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"A project differs from operations because it is…","options":["cheaper","temporary and produces a unique result","always agile","never planned"],"answer":1,"explanation":"Temporary + unique defines a project."},{"prompt":"Which phase formally authorizes the project?","options":["closing","executing","initiating","monitoring and controlling"],"answer":2,"explanation":"Initiating produces the charter and authorization."},{"prompt":"Agile primarily delivers value through…","options":["one final release","short, iterative increments with feedback","avoiding all planning","fixed six-month phases"],"answer":1,"explanation":"Iterations with regular stakeholder feedback."},{"prompt":"The Work Breakdown Structure is organized around…","options":["team roles","deliverables decomposed into work packages","the risk register","the budget only"],"answer":1,"explanation":"The WBS decomposes scope into deliverables and work packages."},{"prompt":"The critical path is the…","options":["path with the most tasks","longest chain of dependent tasks by duration","cheapest set of tasks","list of optional tasks"],"answer":1,"explanation":"It sets the shortest possible project duration."},{"prompt":"Uncontrolled growth of project scope is called…","options":["slack","the critical path","scope creep","a baseline"],"answer":2,"explanation":"Scope creep quietly expands the work."}]}'::jsonb, null, 8),
  (6, 'Cost and the triple constraint', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain the triple constraint and read a basic earned value figure. Warm-up: name the three sides of the triple constraint."},{"heading":"The idea","text":"The *triple constraint* is the tension between *scope*, *schedule*, and *cost* — with quality often placed in the middle. Change one and the others usually shift: add scope and either cost rises or the schedule slips. To estimate cost you build a *budget* from the WBS, and to track it you can use *Earned Value (EV)*. Three key numbers: *Planned Value (PV)* — the budgeted cost of work you planned to have done; *Earned Value (EV)* — the budgeted cost of work actually completed; and *Actual Cost (AC)* — what you truly spent. From these, *Cost Variance = EV − AC* (negative means over budget) and *Schedule Variance = EV − PV* (negative means behind schedule)."},{"heading":"Worked example","text":"Halfway through a project you *planned* to have completed \\$10,000 of work (PV). You have actually finished work worth \\$8,000 in budget terms (EV) and spent \\$9,000 to do it (AC). Schedule Variance = EV − PV = 8,000 − 10,000 = −\\$2,000, so you are behind schedule. Cost Variance = EV − AC = 8,000 − 9,000 = −\\$1,000, so you are over budget. Two clear warning signs from three numbers."},{"heading":"Your turn","text":"Given PV = \\$5,000, EV = \\$6,000, AC = \\$5,500: (1) Cost Variance? (2) Schedule Variance? (3) Ahead or behind schedule, and under or over budget? Answers: (1) EV − AC = +\\$500, (2) EV − PV = +\\$1,000, (3) ahead of schedule and under budget."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating scope, schedule, and cost as independent — they trade off against each other. Mistake: confusing Actual Cost with Earned Value; AC is money spent, EV is budgeted value of completed work. Exit: (a) Which formula gives Cost Variance? (b) A negative Schedule Variance means what? Answers: EV − AC; behind schedule."}]}'::jsonb, 'Triple constraint: scope, schedule, cost. Move one and the others usually move too. EV compares value earned to money spent.', 12),
  (7, 'Risk and stakeholder management', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Identify and prioritize risks and map stakeholders. Warm-up: is a risk something that has already happened, or something uncertain?"},{"heading":"The idea","text":"A *risk* is an *uncertain* event that, if it occurs, affects objectives — it can be a *threat* (harmful) or an *opportunity* (helpful). Teams keep a *risk register*, rating each risk by *probability* and *impact*; roughly, *risk exposure = probability × impact*, which tells you what to tackle first. Responses to threats include *avoid*, *mitigate* (reduce), *transfer* (e.g. insure), and *accept*. *Stakeholders* are anyone who can affect or is affected by the project. A common tool is the *power/interest grid*: high-power, high-interest people you *manage closely*; low-power, low-interest people you simply *monitor*. Good *communication* keeps the right people informed at the right depth."},{"heading":"Worked example","text":"For a software launch, one risk is ''a key vendor delivers late'' with probability 0.4 and an impact of \\$20,000 → exposure ≈ 0.4 × 20,000 = \\$8,000. A second risk, ''minor typo in docs'', has probability 0.5 and impact \\$200 → exposure = \\$100. You focus mitigation on the vendor risk first — perhaps by lining up a backup supplier (transfer/mitigate)."},{"heading":"Your turn","text":"(1) Risk A: probability 0.2, impact \\$50,000 — exposure? (2) Risk B: probability 0.6, impact \\$5,000 — exposure? (3) Which do you prioritize? (4) A high-power, high-interest sponsor should be…? Answers: (1) \\$10,000, (2) \\$3,000, (3) Risk A, (4) managed closely."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking a risk is always bad — opportunities are risks too. Mistake: treating all stakeholders identically instead of by power and interest. Exit: (a) Give the rough formula for risk exposure. (b) Name two threat responses. Answers: probability × impact; any two of avoid, mitigate, transfer, accept."}]}'::jsonb, 'Risk = uncertain event (threat OR opportunity). Rank risks by probability × impact. Engage stakeholders by interest and influence.', 12),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"project charter","translation":"the document that authorizes a project and gives the manager authority","example":"The sponsor signed the charter to formally start the project."},{"term":"Work Breakdown Structure (WBS)","translation":"a hierarchical decomposition of the project''s scope into deliverables and work packages","example":"Each branch of the WBS became a work package we could estimate."},{"term":"critical path","translation":"the longest chain of dependent tasks, which sets the shortest possible project duration","example":"A one-day slip on the critical path delays the whole project by a day."},{"term":"triple constraint","translation":"the trade-off between scope, schedule, and cost","example":"Adding scope forced us to move on cost or schedule — the triple constraint at work."},{"term":"stakeholder","translation":"anyone who can affect or is affected by the project","example":"We mapped every stakeholder on a power/interest grid."},{"term":"iteration (sprint)","translation":"a short, time-boxed cycle in agile that produces a working increment","example":"Each two-week iteration ended with a demo and re-planning of the backlog."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"The triple constraint balances scope, schedule, and…","options":["risk","cost","quality only","stakeholders"],"answer":1,"explanation":"Scope, schedule, and cost — quality often sits in the middle."},{"prompt":"Cost Variance is calculated as…","options":["PV − AC","EV − AC","AC − EV","EV − PV"],"answer":1,"explanation":"EV − AC; negative means over budget."},{"prompt":"A negative Schedule Variance (EV − PV) means the project is…","options":["ahead of schedule","behind schedule","over budget","under budget"],"answer":1,"explanation":"Less value earned than planned = behind schedule."},{"prompt":"Risk exposure is roughly…","options":["probability + impact","probability × impact","impact − probability","cost ÷ time"],"answer":1,"explanation":"Probability times impact ranks which risks to tackle first."},{"prompt":"Insuring against a threat is an example of which response?","options":["avoid","accept","transfer","exploit"],"answer":2,"explanation":"Transfer shifts the impact to a third party."},{"prompt":"On a power/interest grid, a high-power, high-interest stakeholder should be…","options":["ignored","monitored only","managed closely","removed"],"answer":2,"explanation":"Manage key players closely with active engagement."}]}'::jsonb, null, 8),
  (10, 'Applied project: plan a real project', 'writing', '{"sections":[{"heading":"The task","text":"Choose a real project you could plausibly run — a community event, a small app, a home renovation, a team offsite. You will not execute it; you will produce a lightweight plan a colleague could follow, using the tools from this course. Decide up front whether a predictive or agile (or hybrid) approach fits, and say why."},{"heading":"Milestones","text":"1) Charter: one paragraph naming the goal, the sponsor, and success criteria. 2) WBS: break the scope into 4–8 deliverables/work packages. 3) Schedule: list the main activities with rough durations and dependencies, and identify your critical path. 4) Budget: give a ballpark cost tied to the WBS. 5) Risks: log your top three risks with probability × impact and one response each. 6) Stakeholders: name key stakeholders and how you''ll communicate with each."},{"heading":"Self-check rubric","text":"✔ The charter states a clear, measurable goal and names a sponsor. ✔ The WBS is organized by deliverables, not a flat to-do list. ✔ You identified a critical path and justified your approach (predictive/agile/hybrid). ✔ Each top risk has a probability × impact and a concrete response. ✔ Stakeholders are engaged by their power and interest. If all five hold, you''ve planned like a project manager."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0003-0000-4000-8000-000000000009' and l.position = v.pos
);
